CREATE TABLE "categories" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "slug" varchar UNIQUE NOT NULL,
  "image_path" varchar,
  "parent_id" int
);

CREATE TABLE "products" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "slug" varchar UNIQUE NOT NULL,
  "code" varchar UNIQUE NOT NULL,
  "description" text,
  "active" boolean,
  "created_at" timestamp
);

CREATE TABLE "product_categories" (
  "product_id" int,
  "category_id" int,
  PRIMARY KEY ("product_id", "category_id")
);

CREATE TABLE "variants" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int,
  "sku" varchar UNIQUE NOT NULL,
  "name" varchar,
  "price" decimal(10,2),
  "active" boolean,
  "created_at" timestamp
);

CREATE TABLE "option_types" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "code" varchar UNIQUE NOT NULL,
  "sort_order" int
);

CREATE TABLE "variant_options" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" int,
  "option_type_id" int,
  "value" varchar NOT NULL,
  "code" varchar NOT NULL
);

CREATE TABLE "product_images" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int,
  "path" varchar NOT NULL,
  "sort_order" int
);

CREATE TABLE "inventory" (
  "variant_id" int PRIMARY KEY,
  "stock_available" int NOT NULL DEFAULT 0,
  "stock_reserved" int NOT NULL DEFAULT 0,
  "updated_at" timestamp
);

CREATE TABLE "inventory_movements" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" int NOT NULL,
  "type" varchar NOT NULL,
  "quantity" int NOT NULL,
  "reference_type" varchar,
  "reference_id" int,
  "created_at" timestamp
);

CREATE TABLE "users" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar UNIQUE NOT NULL,
  "password_hash" varchar NOT NULL,
  "role" varchar NOT NULL,
  "created_at" timestamp
);

CREATE TABLE "customers" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int UNIQUE,
  "first_name" varchar,
  "last_name" varchar,
  "phone" varchar,
  "created_at" timestamp
);

CREATE TABLE "addresses" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" int,
  "street" varchar,
  "city" varchar,
  "province" varchar,
  "postal_code" varchar,
  "country" varchar,
  "is_default" boolean
);

CREATE TABLE "carts" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" int,
  "created_at" timestamp,
  "status" varchar
);

CREATE TABLE "cart_items" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cart_id" int,
  "variant_id" int,
  "quantity" int
);

CREATE TABLE "orders" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" int,
  "status" varchar,
  "total_amount" decimal(10,2),
  "created_at" timestamp
);

CREATE TABLE "order_items" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" int,
  "variant_id" int,
  "quantity" int,
  "unit_price" decimal(10,2),
  "product_name" varchar,
  "variant_name" varchar,
  "sku" varchar,
  "options_snapshot" text
);

CREATE TABLE "payments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" int,
  "method" varchar,
  "status" varchar,
  "transaction_id" varchar UNIQUE,
  "amount" decimal(10,2),
  "created_at" timestamp
);

CREATE TABLE "shipments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" int,
  "cost" decimal(10,2),
  "status" varchar,
  "shipping_street" varchar,
  "shipping_city" varchar,
  "shipping_province" varchar,
  "shipping_postal_code" varchar
);

CREATE INDEX ON "categories" ("parent_id");

CREATE INDEX ON "variants" ("product_id");

CREATE UNIQUE INDEX ON "variant_options" ("variant_id", "option_type_id");

CREATE INDEX ON "inventory" ("stock_available");

CREATE INDEX ON "inventory" ("stock_reserved");

CREATE INDEX ON "inventory" ("updated_at");

CREATE INDEX ON "inventory_movements" ("variant_id");

CREATE INDEX ON "inventory_movements" ("type");

CREATE INDEX ON "inventory_movements" ("reference_type");

CREATE INDEX ON "inventory_movements" ("reference_id");

CREATE INDEX ON "inventory_movements" ("created_at");

CREATE UNIQUE INDEX ON "cart_items" ("cart_id", "variant_id");

CREATE INDEX ON "order_items" ("order_id");

ALTER TABLE "categories" ADD FOREIGN KEY ("parent_id") REFERENCES "categories" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "product_categories" ADD FOREIGN KEY ("product_id") REFERENCES "products" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "product_categories" ADD FOREIGN KEY ("category_id") REFERENCES "categories" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "variants" ADD FOREIGN KEY ("product_id") REFERENCES "products" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "variant_options" ADD FOREIGN KEY ("variant_id") REFERENCES "variants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "variant_options" ADD FOREIGN KEY ("option_type_id") REFERENCES "option_types" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "product_images" ADD FOREIGN KEY ("product_id") REFERENCES "products" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory" ADD FOREIGN KEY ("variant_id") REFERENCES "variants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_movements" ADD FOREIGN KEY ("variant_id") REFERENCES "variants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "customers" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "addresses" ADD FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "carts" ADD FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "cart_items" ADD FOREIGN KEY ("cart_id") REFERENCES "carts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "cart_items" ADD FOREIGN KEY ("variant_id") REFERENCES "variants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "orders" ADD FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "order_items" ADD FOREIGN KEY ("order_id") REFERENCES "orders" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "order_items" ADD FOREIGN KEY ("variant_id") REFERENCES "variants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "payments" ADD FOREIGN KEY ("order_id") REFERENCES "orders" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "shipments" ADD FOREIGN KEY ("order_id") REFERENCES "orders" ("id") DEFERRABLE INITIALLY IMMEDIATE;
